SET @prov_c := '%s';	
SET	@id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CALL AddCol('hdc','s_breast_screen','result1',' INT(9) DEFAULT 0 ');
CALL AddCol('hdc','s_breast_screen','result2',' INT(9) DEFAULT 0 ');

CREATE TABLE IF NOT EXISTS s_breast_screen(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	result1 int(9) DEFAULT 0,
	result2 int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_breast_screen WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_breast_screen 
(
		SELECT
			 @id,p.check_hosp,p.check_vhid,@send,DATE_FORMAT(now(),'%Y%m%d%H%i%s') as d_com,@b_year+543 as b_year
			,COUNT(DISTINCT p.CID) target
			,COUNT(DISTINCT  IF(o.doctor_screen_date BETWEEN @start_d AND @end_d 
																			OR o.self_screen_date BETWEEN @start_d AND @end_d ,o.cid,NULL)) result
			,COUNT(DISTINCT  IF(o.self_screen_date BETWEEN @start_d AND @end_d ,o.cid,NULL)) result1
			,COUNT(DISTINCT  IF(o.doctor_screen_date BETWEEN @start_d AND @end_d ,o.cid,NULL)) result2
		FROM
			t_person_cid p LEFT JOIN t_breast_screen o ON o.CID=p.CID	
		WHERE	(@b_year-DATE_FORMAT(p.birth,'%Y')) BETWEEN 30 AND 70	AND p.sex IN(2) AND p.DISCHARGE IN(9) AND p.nation IN(99)
			AND p.check_typearea in(1,3)	AND substr(p.check_vhid,1,2)=@prov_c
		GROUP BY	p.check_hosp,p.check_vhid
);

