SET @end_d:=concat(@b_year,'0930');

DROP TEMPORARY TABLE IF EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx ENGINE=MyISAM DEFAULT CHARSET=utf8 IGNORE  AS
SELECT 
p.hospcode,p.pid,p.CID,p.NAME,p.LNAME,p.BIRTH,p.SEX,p.NATION,p.check_typearea,p.addr,p.check_vhid,p.DISCHARGE
,(@b_year-DATE_FORMAT(p.birth,'%Y')) age_y
,o.self_screen,o.self_screen_date,o.self_screen_hospcode,o.self_screen_input
,o.doctor_screen,o.doctor_screen_date,o.doctor_screen_hospcode
FROM 	t_person_cid p 
	LEFT JOIN t_breast_screen o ON o.CID=p.CID	
WHERE	(@b_year-DATE_FORMAT(p.birth,'%Y')) BETWEEN 30 AND 70	AND p.sex IN(2) AND p.DISCHARGE IN(9) AND p.nation IN(99)
		AND p.check_typearea in(1,3) AND substr(p.check_vhid,1,2)=@prov_c ;

SELECT
h.hoscode,h.hosname,d.pid,d.CID,d.NAME,d.LNAME,d.BIRTH,d.SEX,d.NATION,d.check_typearea,d.addr,d.check_vhid,d.DISCHARGE
,d.age_y,d.self_screen,d.self_screen_date,d.self_screen_hospcode,d.self_screen_input
,d.doctor_screen,d.doctor_screen_date,d.doctor_screen_hospcode
